def getConnectionQuantity(uuid, configs, connections, componentTypes, configAttribute=[]):
	#determine if the target component is a gateway
	def confirmComponentType(uuid):
		if uuid in configs.keys():
			comonentType=configs[uuid]['type']
			if comonentType in ['cloud', 'standard', 'edge', 'panel']:
				return True
		return False

	def getConnections(uuid):
		if uuid in configs.keys():
			return configs[uuid]['config']['connections']
		return None

	isServer=confirmComponentType(uuid)
	quantity={}
	for cType in componentTypes:
		quantity[cType]=[]

	if isServer:
		connectionUUIDs=getConnections(uuid)
		#get component Connected to server from connection
		for connection in connectionUUIDs:
			individualQuantitiy=0
			myConnection= None
			cUUID=connections[connection].keys()
			if cUUID[0]!=uuid:
				myConnection=cUUID[0]
			elif cUUID[1]!=uuid:
				myConnection=cUUID[1]
			#get myConnection config
			if myConnection is not None:
				connectionConfig=configs[myConnection]
				#does myConnection match desired componentType
				if connectionConfig['type'] in componentTypes:
					if len(configAttribute)>0:
						compUuid={}
						for attribute in configAttribute:
							if attribute in connectionConfig['config'].keys():
								compUuid['uuid']=connection
								compUuid[attribute]=connectionConfig['config'][attribute]

						quantity[connectionConfig['type']].append(compUuid)

					else:
						compUuid={}
						compUuid['uuid']=connection
						compUuid['count']=1
						quantity[connectionConfig['type']].append(compUuid)

	return quantity

